theorem eigenvalues_nonneg_of_gram_psd {n : ℕ} {G : Matrix (Fin n) (Fin n) ℝ}
    {U : Matrix (Fin n) (Fin n) ℝ} {lam : Fin n → ℝ}
    (hU : Uᵀ * U = 1) (hG : G = U * diagonal lam * Uᵀ)
    (hpsd : ∀ v : Fin n → ℝ, 0 ≤ ∑ i, ∑ j, v i * G i j * v j) (k : Fin n) :
    0 ≤ lam k

theorem matrixExpectation_eq_zero {n : ℕ} {A : α → Matrix (Fin n) (Fin n) ℝ}
    (h : ∀ i j, matrixEntryExpectation A i j = 0) :
    matrixExpectation A = 0

theorem wigner_first_moment_zero {n : ℕ} {A : α → Matrix (Fin n) (Fin n) ℝ}
    (h : ∀ i j, matrixEntryExpectation A i j = 0) :
    (∑ ω : α, (A ω).trace) / (Fintype.card α : ℝ) = 0
